+function withSpecies(callback) {
+  Object.defineProperty(Uint8Array, Symbol.species, {
+    configurable: true,
+    value: Float64Array,
+  });
+  try {
+    return callback();
+  } finally {
+    delete Uint8Array[Symbol.species];
+  }
+}
